/**
 * The inventory, mercenary and stash drawn on D2R's own panels.
 *
 * The art and every rect come from the game (`hdui.json`, generated by
 * `scripts/generate-hd-assets.mjs` from its layout files), at the items' 30 pixels per cell, so an
 * item placed at a slot's rect sits in the panel's own frame and a grid's items on its own cells.
 * Only the D2R art style draws these; the classic style keeps the plain paperdoll and grids, and
 * so does any grid no panel was drawn for. Three panels the game does not ship are composed from
 * its art by `scripts/compose-lod-panels.mjs`: the mercenary's with the cube in it, the classic
 * stash (6x4), and the LoD expansion's 6x8 stash, which is also PlugY's page size.
 *
 * Items are `ItemCell`s like everywhere else, so tooltips and the context menu behave the same.
 */

import { useState, type CSSProperties, type ReactNode } from "react";
import { useTooltipTextStyle } from "@/features/items";
import { ItemSprite } from "@/lib/rendering";
import {
  composedPanelUrl,
  useUiSprite,
  type UiGrid,
  type UiPanels,
  type UiRect,
} from "@/lib/rendering/hdUi";
import { ActiveDot } from "./CharacterChrome";
import { useGameNames } from "./gameNames";
import { ItemCell } from "./ItemCell";
import {
  CONTAINER_LABELS,
  stashPageLabel,
  type DisplayContainer,
  type DisplayIdentity,
  type DisplayItem,
  type DisplayMercInfo,
  levelProgress,
  type LevelProgress,
  type DisplayStashPage,
} from "./contracts";

/** Pixels per cell: the panels are generated at the items' scale. */
const CELL = 30;

/**
 * The panels `scripts/compose-lod-panels.mjs` composes, which no layout file describes. Their rects
 * are the script's, in the game's full-resolution pixels (98 per cell), scaled the way the
 * generator scales a layout's.
 */
const s = (v: number) => Math.round((v * CELL) / 98);
/**
 * A layout `pointSize` as CSS pixels at our scale: points at the usual 96 dpi (4/3 px each) on
 * the 4K layout, scaled like every rect. Treating a point as one layout pixel read visibly small.
 */
const pt = (v: number) => Math.round(((v * 4) / 3) * (CELL / 98));
/**
 * The game's font sizes (`_profilehd.json`) used on these panels, for text in the tooltip
 * lettering (`useTooltipTextStyle`: the reader's item font, small caps). The tab labels keep
 * their own smaller sizes, which suit the tab art.
 */
const FONT = {
  title: pt(38), // $LargeFontSize: panel titles, a hireling's name
  gold: pt(34), // $XMediumLargeFontSize: StyleGoldAmount
  detail: pt(28), // $XMediumPanelFontSize: a hireling's "Level N"
  label: pt(26), // $MediumFontSize: the "Past" toggle, page text
};
const COMPOSED_SIZE: [number, number] = [s(1162), s(1507)];
/** The mercenary panel with the cube where its statistics were. */
const MERC_CUBE = {
  background: "panel_merc_cube.png",
  grid: { at: [s(434), s(955)], cols: 3, rows: 4 } satisfies UiGrid,
};
/**
 * The classic stash panel (6x4, the same in both games' classic mode) and the LoD expansion's
 * 6x8 composed from it. Both keep the classic panel's gold readout and its title bar.
 */
const SMALL_STASHES = [
  {
    background: "panel_stash_lod.png",
    grid: { at: [s(288), s(357)], cols: 6, rows: 8 } satisfies UiGrid,
  },
  {
    background: "panel_stash_classic.png",
    grid: { at: [s(288), s(749)], cols: 6, rows: 4 } satisfies UiGrid,
  },
];
const SMALL_STASH_GOLD: UiRect = [s(487), s(1306), s(249), s(48)];
const SMALL_STASH_GOLD_BUTTON: [number, number] = [s(427), s(1303)];
/**
 * The cover RotW draws over an advanced stash page's cube grid (`horadriccube_cover`). The
 * viewer keeps the cube under the mercenary or on its own panel, so the pages show this.
 */
const CUBE_COVER = { file: "panel_cube_cover.png", at: [s(432), s(786)] };
/**
 * The stash's previous-season toggle (`PreviousSeasonToggleDisplay` at 950,65): the checkbox 8 to
 * the right of that origin, the "Past" label (`@oldStash`) right-aligned against it in
 * `PanelTitleColor` at `$MediumFontSize` (26), and the game's tooltip.
 */
const PAST_TOGGLE = {
  checkbox: [s(958), s(65)],
  size: [21, 20],
  fontSize: FONT.label,
  label: "Past",
  tooltip:
    "Enable this to view your previous ladder season's shared stash tabs.\n" +
    "Items can only be removed from these shared stash tabs and will be deleted when the next season starts.",
};
/** `$InGamePanelTitleRect`, where a page's name and its arrows go. */
const PANEL_TITLE: UiRect = [s(91), s(64), s(972), s(71)];
/**
 * A wearer's title: the name line in the title bar, and its experience bar (the hireling panel's
 * `Hireling_ExpBar` fill, used for both wearers) beneath it, laid over the gold separator line
 * that closes the title bar (y 133 at 4K) so the bar takes the line's place.
 */
const NAME_LINE: UiRect = [
  PANEL_TITLE[0],
  PANEL_TITLE[1] - 1,
  PANEL_TITLE[2],
  PANEL_TITLE[3] - 2,
];
const XP_BAR: UiRect = [PANEL_TITLE[0] + 4, s(133) - 1, PANEL_TITLE[2] - 8, 3];

/** The game's text colours (`_profilehd.json`). */
const COLOR = {
  gold: "rgb(209, 195, 120)", // FontColorCurrencyGold
  title: "rgb(199, 179, 119)", // PanelTitleColor
  tabActive: "rgb(240, 240, 240)", // TabsActiveTextColor
  tabInactive: "rgb(125, 141, 144)", // TabsInactiveTextColor
  white: "rgb(255, 255, 255)",
};

/** `AdvancedStashSlotWidget.emptyOpacity`'s default (d2r.exe sets 0x3E4CCCCD). */
const EMPTY_SLOT_OPACITY = 0.2;

/** The game's `DefaultDropShadow` (3px at 4K), at our scale. */
const SHADOW = "1px 1px 0 rgba(0, 0, 0, 0.78)";

const rectStyle = ([x, y, width, height]: UiRect): CSSProperties => ({
  position: "absolute",
  left: x,
  top: y,
  width,
  height,
});

/** One UI sprite, absolutely placed; nothing until it has loaded. */
function UiImage({
  name,
  x,
  y,
  style,
}: {
  name: string | undefined;
  x: number;
  y: number;
  style?: CSSProperties;
}) {
  const url = useUiSprite(name);
  if (!url) return null;
  return (
    <img
      src={url}
      alt=""
      draggable={false}
      className="pointer-events-none absolute select-none"
      style={{ left: x, top: y, ...style }}
    />
  );
}

/**
 * A panel: its background art, at its own size, with everything else placed over it. The art is
 * a sprite of the archives, or with `composed` one of the loose composed panels.
 */
function Panel({
  background,
  size,
  composed,
  children,
}: {
  background: string;
  size: [number, number];
  composed?: boolean;
  children: ReactNode;
}) {
  return (
    <div
      className="relative shrink-0"
      style={{ width: size[0], height: size[1] }}
    >
      {composed ? (
        <img
          src={composedPanelUrl(background)}
          alt=""
          draggable={false}
          className="pointer-events-none absolute left-0 top-0 select-none"
        />
      ) : (
        <UiImage name={background} x={0} y={0} />
      )}
      {children}
    </div>
  );
}

/** Text in a panel rect, the game's way: its colour, its drop shadow, the tooltip lettering. */
function PanelText({
  rect,
  color,
  size,
  align = "center",
  children,
}: {
  rect: UiRect;
  color: string;
  size: number;
  align?: "left" | "center";
  children: ReactNode;
}) {
  const panelFont = useTooltipTextStyle();
  return (
    <div
      className="pointer-events-none flex items-center whitespace-nowrap leading-none"
      style={{
        ...rectStyle(rect),
        ...panelFont,
        justifyContent: align === "left" ? "flex-start" : "center",
        paddingLeft: align === "left" ? 4 : 0,
        color,
        fontSize: size,
        textShadow: SHADOW,
      }}
    >
      {children}
    </div>
  );
}

/**
 * A gold amount the way the panels show it: the gold button, and the figure left-aligned in the
 * readout after it (`StyleGoldAmount` aligns left).
 */
function GoldReadout({
  button,
  rect,
  gold,
}: {
  button: [number, number];
  rect: UiRect;
  gold: number;
}) {
  return (
    <>
      <UiImage name="gold_button" x={button[0]} y={button[1]} />
      <PanelText rect={rect} color={COLOR.gold} size={FONT.gold} align="left">
        {gold.toLocaleString()}
      </PanelText>
    </>
  );
}

/**
 * Who the character is, in the panel's title bar where the game writes the panel's name: the
 * character's name in the title colour (`$StyleTitleBlock`, 38), then its level and class.
 */
function IdentityTitle({ identity }: { identity: DisplayIdentity }) {
  const names = useGameNames();
  // A player's thresholds are experience.txt's: the game keeps stats 29/30 for hirelings only.
  const progress = levelProgress(
    identity.experience,
    names.levelExperience(identity.level),
    names.levelExperience(identity.level + 1),
  );
  return (
    <NameTitle
      name={identity.name}
      level={identity.level}
      kind={names.characterClass(identity.charClass)}
      progress={progress}
    />
  );
}

/**
 * A wearer's name and "Level N <kind>" in a panel's title bar, left-aligned — the name in the
 * title colour, the level line in white beside it — with its experience bar beneath. Shared by
 * the character and the mercenary.
 */
function NameTitle({
  name,
  level,
  kind,
  progress,
}: {
  name: string;
  level: number;
  kind: string | null;
  progress: LevelProgress | null;
}) {
  return (
    <>
      <PanelText
        rect={NAME_LINE}
        color={COLOR.title}
        size={FONT.title}
        align="left"
      >
        {name}
        <span
          style={{ color: COLOR.white, fontSize: FONT.detail, marginLeft: 8 }}
        >
          Level {level}
          {kind ? ` ${kind}` : ""}
        </span>
      </PanelText>
      {progress && <ExperienceBar progress={progress} level={level} />}
    </>
  );
}

/**
 * The experience bar under a name: the game's fill drawn to the level fraction over a dark track,
 * and on hover a tooltip in the game's own tooltip style (black at 75%) with the figures.
 */
function ExperienceBar({
  progress,
  level,
}: {
  progress: LevelProgress;
  level: number;
}) {
  const panelFont = useTooltipTextStyle();
  const [hovered, setHovered] = useState(false);
  const [x, y, width, height] = XP_BAR;
  const rows: [string, string][] = [
    ["Experience", progress.experience.toLocaleString()],
    [`Level ${level}`, progress.last.toLocaleString()],
    [`Level ${level + 1}`, progress.next.toLocaleString()],
    ["To go", progress.remaining.toLocaleString()],
  ];
  return (
    <div
      className="absolute z-10"
      // A taller hit area than the 3px bar, so it can be hovered at all.
      style={{ left: x, top: y - 4, width, height: height + 8 }}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
    >
      <div
        className="pointer-events-none absolute overflow-hidden"
        style={{
          left: 0,
          top: 4,
          width,
          height,
          background: "rgba(0, 0, 0, 0.6)",
        }}
      >
        <img
          src={composedPanelUrl("panel_merc_expbar.png")}
          alt=""
          draggable={false}
          className="block max-w-none select-none"
          style={{
            width,
            height,
            clipPath: `inset(0 ${(1 - progress.fraction) * 100}% 0 0)`,
          }}
        />
      </div>
      {hovered && (
        <div
          className="pointer-events-none absolute left-1/2 top-full mt-1 -translate-x-1/2 whitespace-nowrap leading-tight"
          style={{
            ...panelFont,
            backgroundColor: "rgba(0, 0, 0, 0.75)",
            padding: "0.33em 0.56em",
            fontSize: FONT.label,
            color: COLOR.white,
          }}
        >
          <div className="text-center" style={{ color: COLOR.title }}>
            {(progress.fraction * 100).toFixed(1)}% through level {level}
          </div>
          {rows.map(([label, value]) => (
            <div key={label} className="flex justify-between gap-4">
              <span>{label}</span>
              <span>{value}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

/** A container's items on a panel's grid. */
function PanelGrid({
  container,
  grid,
}: {
  container: DisplayContainer;
  grid: UiGrid;
}) {
  return (
    <>
      {container.items.map((item, i) => {
        const width = Math.max(item.width, 1) * CELL;
        const height = Math.max(item.height, 1) * CELL;
        return (
          <ItemCell
            key={`${item.gid}-${item.x}-${item.y}-${i}`}
            item={item}
            className="absolute"
            style={{
              left: grid.at[0] + item.x * CELL,
              top: grid.at[1] + item.y * CELL,
              width,
              height,
            }}
            spriteStyle={{ width, height }}
          />
        );
      })}
    </>
  );
}

/** A paperdoll slot: the item centred in it, or the game's silhouette while it is empty. */
function PanelSlot({
  rect,
  item,
  empty,
}: {
  rect: UiRect;
  item: DisplayItem | undefined;
  empty: string | undefined;
}) {
  if (!item) return <UiImage name={empty} x={rect[0]} y={rect[1]} />;
  return (
    <ItemCell
      item={item}
      cellKind="slot"
      className="flex items-center justify-center"
      style={rectStyle(rect)}
    />
  );
}

/** Items of a slot container by equip location (carried in `x`). */
function bySlot(container: DisplayContainer | undefined) {
  const map = new Map<number, DisplayItem>();
  for (const item of container?.items ?? []) map.set(item.x, item);
  return map;
}

/**
 * Whether the panels can draw these: their art and the grids they were drawn for. A container of
 * another size (a 1.14d stash is 6x8) goes to the plain grids instead of being cropped or spilled.
 */
export function stashFitsPanel(panels: UiPanels, pages: DisplayStashPage[]) {
  const { cols, rows } = panels.stash.grid;
  return pages
    .filter((p) => p.type !== "advanced")
    .every((p) => p.container.width === cols && p.container.height === rows);
}

export function inventoryFitsPanel(
  panels: UiPanels,
  inventory: DisplayContainer | undefined,
) {
  const { cols, rows } = panels.inventory.grid;
  return !inventory || (inventory.width === cols && inventory.height === rows);
}

/**
 * The character's panel: paperdoll, weapon-set tabs, inventory grid and gold, as the game lays
 * them out. The tabs pick which weapon set the hands show; the set the character has active is
 * marked, and the choice stays put while it flips live (the same rule as the plain paperdoll).
 */
export function GameInventoryPanel({
  panels,
  equipped,
  inventory,
  gold,
  expansion,
  activeSet,
  identity,
}: {
  panels: UiPanels;
  equipped: DisplayContainer | undefined;
  inventory: DisplayContainer | undefined;
  gold: number;
  expansion: boolean;
  activeSet: 0 | 1;
  identity: DisplayIdentity;
}) {
  const [selectedSet, setSelectedSet] = useState<0 | 1>(activeSet);
  const panel = panels.inventory;
  const worn = bySlot(equipped);
  // The active set's weapons are in 4/5, the other set's in 11/12.
  const showingActive = selectedSet === activeSet;
  const itemAt = (location: number) =>
    worn.get(
      showingActive
        ? location
        : location === 4
          ? 11
          : location === 5
            ? 12
            : location,
    );

  const tabs = panel.weaponTabs;
  return (
    <Panel background={panel.background} size={panel.size}>
      <IdentityTitle identity={identity} />
      {Object.entries(panel.slots).map(([location, slot]) => (
        <PanelSlot
          key={location}
          rect={slot.rect}
          item={itemAt(Number(location))}
          empty={slot.empty}
        />
      ))}
      {expansion &&
        tabs.at.map(([x, y], hand) => (
          <div key={hand}>
            <UiImage name={tabs.sprites[selectedSet]} x={x} y={y} />
            {([0, 1] as const).map((set) => {
              const [lx, ly, lw, lh] = tabs.labels[set];
              const dx = x - tabs.at[0][0];
              return (
                <button
                  key={set}
                  type="button"
                  onClick={() => setSelectedSet(set)}
                  title={
                    set === activeSet
                      ? "Active weapon set"
                      : `Weapon set ${set === 0 ? "I" : "II"}`
                  }
                  className="absolute flex items-center justify-center gap-0.5 leading-none"
                  style={{
                    left: lx + dx,
                    top: ly,
                    width: lw,
                    height: lh,
                    color:
                      set === selectedSet ? COLOR.tabActive : COLOR.tabInactive,
                    fontSize: 10,
                    textShadow: SHADOW,
                  }}
                >
                  {set === 0 ? "I" : "II"}
                  {set === activeSet && <ActiveDot />}
                </button>
              );
            })}
          </div>
        ))}
      {inventory && <PanelGrid container={inventory} grid={panel.grid} />}
      <GoldReadout button={panel.goldButton} rect={panel.gold} gold={gold} />
    </Panel>
  );
}

/**
 * The mercenary's panel. With a `cube` it is the composed panel that holds the Horadric Cube
 * where the statistics were: while a mercenary is alive the cube is drawn here, rather than on
 * its own panel or in the stash. Without one, the game's panel, its statistics block empty.
 */
export function GameMercPanel({
  panels,
  merc,
  cube,
  info,
}: {
  panels: UiPanels;
  merc: DisplayContainer;
  cube?: DisplayContainer;
  info?: DisplayMercInfo;
}) {
  const panel = panels.merc;
  const worn = bySlot(merc);
  return (
    <Panel
      background={cube ? MERC_CUBE.background : panel.background}
      size={cube ? COMPOSED_SIZE : panel.size}
      composed={!!cube}
    >
      {info && <MercInfo info={info} />}
      {Object.entries(panel.slots).map(([location, slot]) => (
        <PanelSlot
          key={location}
          rect={slot.rect}
          item={worn.get(Number(location))}
          empty={slot.empty}
        />
      ))}
      {cube && <PanelGrid container={cube} grid={MERC_CUBE.grid} />}
    </Panel>
  );
}

/**
 * What the game writes about a mercenary, where the character's own is: its name, "Level N
 * <kind>" and experience bar in the panel's title bar.
 */
function MercInfo({ info }: { info: DisplayMercInfo }) {
  const type = useGameNames().monster(info.classId);
  return (
    <NameTitle
      name={info.name}
      level={info.level}
      kind={type}
      progress={info.progress}
    />
  );
}

/** A page-step arrow, drawn in the frame the game draws for its state. */
function PageArrow({
  arrow,
  side,
  disabled,
  onClick,
}: {
  arrow: UiPanels["stash"]["pages"]["left"];
  side: "left" | "right";
  disabled: boolean;
  onClick: () => void;
}) {
  const [hovered, setHovered] = useState(false);
  const [pressed, setPressed] = useState(false);
  const frame = disabled
    ? arrow.frames.disabled
    : pressed
      ? arrow.frames.pressed
      : hovered
        ? arrow.frames.hovered
        : arrow.frames.normal;
  const url = useUiSprite(`stash_arrow_${side}_${frame}`);
  return (
    <button
      type="button"
      aria-label={side === "left" ? "Previous stash page" : "Next stash page"}
      disabled={disabled}
      onClick={onClick}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => {
        setHovered(false);
        setPressed(false);
      }}
      onMouseDown={() => setPressed(true)}
      onMouseUp={() => setPressed(false)}
      className="disabled:cursor-not-allowed"
      style={{
        ...rectStyle(arrow.rect),
        backgroundImage: url ? `url(${url})` : undefined,
        backgroundSize: "100% 100%",
      }}
    />
  );
}

/** The advanced pages, which RotW lays out slot by item code. */
type AdvancedTab = "gems" | "materials" | "runes";
const ADVANCED_ORDER: AdvancedTab[] = ["gems", "materials", "runes"];

/** One tab of the stash bar: what it is called, and what it shows. */
interface StashTab {
  key: string;
  label: string;
  /** The grid pages the tab steps through; empty for an advanced tab. */
  pages: DisplayStashPage[];
  advanced?: AdvancedTab;
  /** Which background the panel draws behind it. */
  background: string;
}

/**
 * The stash as the game draws it, in one of its two shapes.
 *
 * RotW (the stash holds advanced pages): Personal, Shared and the advanced Gems, Materials and
 * Runes tabs, the shared pages stepped through with the page arrows, the advanced pages laid out
 * slot by item code — an empty slot drawing its item faded, as the game does. RotW keeps the
 * Horadric Cube on those pages; the viewer does not, drawing it under the mercenary or on its own
 * panel instead, so it is in one place whatever the game.
 *
 * Before RotW there are no advanced pages and each page is a tab of its own: Personal, then one
 * per shared page, on the older tab art. Should there be more pages than that bar holds, they
 * fall back to the RotW bar and its arrows rather than spilling off the panel.
 */
export function GameStashPanel({
  panels,
  pages,
}: {
  panels: UiPanels;
  pages: DisplayStashPage[];
}) {
  const panelFont = useTooltipTextStyle();
  const panel = panels.stash;
  const [labelPersonal, labelShared] = panel.tabs.labels;
  // The previous season's shared tabs (remove-only) take the shared tabs' places while the
  // game's "Past" toggle is on, and are out of sight otherwise; the toggle exists only when
  // there are any. Personal pages are a character's own and never change with it.
  const [showPast, setShowPast] = useState(false);
  const hasPast = pages.some((p) => p.removeOnly);
  const past = hasPast && showPast;
  const inSeason = (p: DisplayStashPage) =>
    p.kind === "personal" || p.removeOnly === past;
  const grids = (kind: "personal" | "shared") =>
    pages.filter(
      (p) => p.kind === kind && p.type !== "advanced" && inSeason(p),
    );
  const personal = grids("personal");
  const shared = grids("shared");
  const advancedItems = pages
    .filter((p) => p.type === "advanced" && inSeason(p))
    .flatMap((p) => p.container.items);
  const rotw = pages.some((p) => p.type === "advanced");
  const perPage =
    !rotw && 1 + shared.length <= panel.pageTabs.count && personal.length <= 1;

  const tabs: StashTab[] = [];
  if (personal.length > 0 || !perPage) {
    tabs.push({
      key: "personal",
      label: labelPersonal,
      pages: personal,
      background: panel.backgrounds.personal,
    });
  }
  if (perPage) {
    shared.forEach((page, i) =>
      tabs.push({
        key: `shared-${i}`,
        label: page.name || labelShared,
        pages: [page],
        background: panel.backgrounds.shared,
      }),
    );
  } else if (shared.length > 0) {
    tabs.push({
      key: "shared",
      label: labelShared,
      pages: shared,
      background: panel.backgrounds.shared,
    });
  }
  if (rotw) {
    ADVANCED_ORDER.forEach((advanced, i) =>
      tabs.push({
        key: advanced,
        label: panel.tabs.labels[2 + i],
        pages: [],
        advanced,
        background: panel.advanced[advanced].background,
      }),
    );
  }

  const [selected, setSelected] = useState<string>(tabs[0]?.key ?? "");
  const [pageIndex, setPageIndex] = useState<Record<string, number>>({});
  const tab = tabs.find((t) => t.key === selected) ?? tabs[0];
  if (!tab) return null;

  const index = Math.min(
    pageIndex[tab.key] ?? 0,
    Math.max(tab.pages.length - 1, 0),
  );
  const page = tab.pages[index];
  const advanced = tab.advanced ? panel.advanced[tab.advanced] : null;

  // The bar: RotW's five fixed slots, or the older one-tab-per-page art.
  const bar = perPage
    ? {
        at: panel.pageTabs.at,
        size: panel.pageTabs.size,
        sprites: panel.pageTabs.sprites,
      }
    : { at: panel.tabs.at, size: panel.tabs.size, sprites: panel.tabs.sprites };
  const slotOf = (t: StashTab, i: number) =>
    perPage
      ? i
      : t.advanced
        ? 2 + ADVANCED_ORDER.indexOf(t.advanced)
        : t.key === "shared"
          ? 1
          : 0;

  // Items by code on an advanced page; a slot nothing fills draws its item faded.
  const byCode = new Map<string, DisplayItem>();
  for (const item of advancedItems)
    byCode.set(item.hd?.code ?? item.code, item);

  return (
    <Panel background={tab.background} size={panel.size}>
      {tabs.map((t, i) => {
        const active = t === tab;
        return (
          <button
            key={t.key}
            type="button"
            onClick={() => setSelected(t.key)}
            className="absolute flex items-center justify-center leading-none"
            style={{
              left: bar.at[0] + slotOf(t, i) * bar.size[0],
              top: bar.at[1],
              width: bar.size[0],
              height: bar.size[1],
              ...panelFont,
              color: active ? COLOR.tabActive : COLOR.tabInactive,
              fontSize: 9,
              textShadow: SHADOW,
            }}
          >
            <UiImage
              name={bar.sprites[active ? 1 : 0]}
              x={0}
              y={0}
              style={{ width: "100%", height: "100%" }}
            />
            <span className="relative">{t.label}</span>
          </button>
        );
      })}

      {hasPast && (
        <PastToggle
          on={showPast}
          onChange={setShowPast}
          seasons={pages.filter((p) => p.removeOnly).map((p) => p.season)}
        />
      )}

      {page && <PanelGrid container={page.container} grid={panel.grid} />}

      {advanced &&
        Object.entries(advanced.slots).map(([code, rect]) => {
          const item = byCode.get(code);
          if (!item)
            return <FadedSlotItem key={code} code={code} rect={rect} />;
          return (
            <div key={code} style={rectStyle(rect)}>
              <ItemCell
                item={item}
                cellKind="slot"
                className="flex h-full w-full items-center justify-center"
              />
              {item.stackCount !== undefined && (
                <span
                  className="pointer-events-none absolute bottom-0 right-0.5 leading-none"
                  style={{
                    ...panelFont,
                    color: COLOR.white,
                    fontSize: 9,
                    textShadow: SHADOW,
                  }}
                >
                  {item.stackCount}
                </span>
              )}
            </div>
          );
        })}

      {advanced && (
        <img
          src={composedPanelUrl(CUBE_COVER.file)}
          alt=""
          draggable={false}
          className="pointer-events-none absolute select-none"
          style={{ left: CUBE_COVER.at[0], top: CUBE_COVER.at[1] }}
        />
      )}

      {tab.pages.length > 1 && (
        <>
          <PageArrow
            arrow={panel.pages.left}
            side="left"
            disabled={index === 0}
            onClick={() => setPageIndex({ ...pageIndex, [tab.key]: index - 1 })}
          />
          <PanelText
            rect={panel.pages.text}
            color={COLOR.title}
            size={FONT.label}
          >
            {page?.name ||
              panel.pages.format
                .replace("%u", String(index + 1))
                .replace("%u", String(tab.pages.length))}
          </PanelText>
          <PageArrow
            arrow={panel.pages.right}
            side="right"
            disabled={index === tab.pages.length - 1}
            onClick={() => setPageIndex({ ...pageIndex, [tab.key]: index + 1 })}
          />
        </>
      )}

      {page && (
        <GoldReadout
          button={panel.goldButton}
          rect={panel.gold}
          gold={page.gold}
        />
      )}
    </Panel>
  );
}

/**
 * The stash's "Past" toggle (`ShowPreviousLadderSeasonToggle`): the game's checkbox at its
 * place in the title bar, its label right-aligned against it, its explanation as the tooltip.
 */
function PastToggle({
  on,
  onChange,
  seasons,
}: {
  on: boolean;
  onChange: (on: boolean) => void;
  /** The seasons the remove-only pages belong to (0 = not reported). */
  seasons: number[];
}) {
  const panelFont = useTooltipTextStyle();
  // The label is the game's own; which season it reveals goes in the tooltip after the game's.
  const known = [...new Set(seasons.filter((n) => n > 0))].sort(
    (a, b) => a - b,
  );
  const tooltip =
    known.length > 0
      ? `${PAST_TOGGLE.tooltip}\n\nSeason ${known.join(", ")}`
      : PAST_TOGGLE.tooltip;
  const [hovered, setHovered] = useState(false);
  const frame = on ? (hovered ? 6 : 4) : hovered ? 3 : 0;
  return (
    <button
      type="button"
      role="checkbox"
      aria-checked={on}
      onClick={() => onChange(!on)}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      title={tooltip}
      className="absolute flex items-center gap-0.5 leading-none"
      style={{
        right: COMPOSED_SIZE[0] - PAST_TOGGLE.checkbox[0] - PAST_TOGGLE.size[0],
        top: PAST_TOGGLE.checkbox[1],
        height: PAST_TOGGLE.size[1],
        ...panelFont,
        // As the game sets it: the face's own small capitals (Exocet's lowercase ARE small caps,
        // so CSS small-caps on top synthesised a second, smaller set) and `$MinimumSpacing`'s
        // kerning of 0.88, i.e. letters drawn 12% tighter.
        fontVariantCaps: "normal",
        letterSpacing: "-0.06em",
        color: COLOR.title,
        fontSize: PAST_TOGGLE.fontSize,
        textShadow: SHADOW,
      }}
    >
      <span>{PAST_TOGGLE.label}</span>
      <img
        src={composedPanelUrl(`panel_checkbox_${frame}.png`)}
        alt=""
        draggable={false}
        className="pointer-events-none select-none"
      />
    </button>
  );
}

/**
 * An advanced slot nothing fills: the game draws the slot's own item there at its
 * `emptyOpacity` (0.2, `AdvancedStashSlotWidget`), so the page reads as a set to collect.
 */
function FadedSlotItem({ code, rect }: { code: string; rect: UiRect }) {
  return (
    <div
      className="pointer-events-none flex items-center justify-center"
      style={{ ...rectStyle(rect), opacity: EMPTY_SLOT_OPACITY }}
    >
      <ItemSprite code={code} hd={{ code, variant: 0 }} alt="" />
    </div>
  );
}

/** The Horadric Cube on its own panel, for a game that does not keep it in the stash. */
export function GameCubePanel({
  panels,
  cube,
}: {
  panels: UiPanels;
  cube: DisplayContainer;
}) {
  const panel = panels.cube;
  return (
    <Panel background={panel.background} size={panel.size}>
      <PanelGrid container={cube} grid={panel.grid} />
    </Panel>
  );
}

/**
 * Which composed classic panel draws these pages: every grid page must be its size (6x8 for the
 * LoD expansion and PlugY, 6x4 for classic). Null when none fits.
 */
export function smallStashLayout(pages: DisplayStashPage[]) {
  const grids = pages.filter((p) => p.type !== "advanced");
  if (grids.length === 0) return null;
  return (
    SMALL_STASHES.find(({ grid }) =>
      grids.every(
        (p) =>
          p.container.width === grid.cols && p.container.height === grid.rows,
      ),
    ) ?? null
  );
}

/**
 * The stash on the classic panel, or on the LoD expansion's 6x8 composed from it.
 *
 * The classic panel has no tab bar, so pages are stepped through with the game's page arrows in
 * its title bar, in list order — every personal page, then every shared one (PlugY's) — with
 * the page's name between them. A lone page is titled "Stash", as the game titles it.
 */
export function GameSmallStashPanel({
  panels,
  pages,
}: {
  panels: UiPanels;
  pages: DisplayStashPage[];
}) {
  const [index, setIndex] = useState(0);
  const layout = smallStashLayout(pages);
  const grids = pages.filter((p) => p.type !== "advanced");
  if (!layout || grids.length === 0) return null;
  const position = Math.min(index, grids.length - 1);
  const page = grids[position];

  const [tx, ty, tw, th] = PANEL_TITLE;
  const arrowAt = (
    arrow: UiPanels["stash"]["pages"]["left"],
    side: "left" | "right",
  ) => {
    const [, , w, h] = arrow.rect;
    const x = side === "left" ? tx + 4 : tx + tw - w - 4;
    return {
      ...arrow,
      rect: [x, ty + Math.round((th - h) / 2), w, h] as UiRect,
    };
  };

  return (
    <Panel background={layout.background} size={COMPOSED_SIZE} composed>
      <PanelText rect={PANEL_TITLE} color={COLOR.title} size={FONT.title}>
        {grids.length > 1 ? stashPageLabel(page) : CONTAINER_LABELS.stash}
      </PanelText>
      {grids.length > 1 && (
        <>
          <PageArrow
            arrow={arrowAt(panels.stash.pages.left, "left")}
            side="left"
            disabled={position === 0}
            onClick={() => setIndex(position - 1)}
          />
          <PageArrow
            arrow={arrowAt(panels.stash.pages.right, "right")}
            side="right"
            disabled={position === grids.length - 1}
            onClick={() => setIndex(position + 1)}
          />
        </>
      )}
      <PanelGrid container={page.container} grid={layout.grid} />
      <GoldReadout
        button={SMALL_STASH_GOLD_BUTTON}
        rect={SMALL_STASH_GOLD}
        gold={page.gold}
      />
    </Panel>
  );
}

export function cubeFitsPanel(
  panels: UiPanels,
  cube: DisplayContainer | undefined,
) {
  const { cols, rows } = panels.cube.grid;
  return !!cube && cube.width === cols && cube.height === rows;
}
